// Example usage of the acme-retry package.
//
// Note: I could not inspect acme-retry locally because this workspace does not
// contain node_modules/acme-retry and require.resolve('acme-retry') fails.
// This example assumes the common retry API shape:
//
//   retry(fn, { retries: 5 })
//
// where `fn` may be async and is called again until it resolves or the retry
// limit is exhausted.

const retry = require('acme-retry');

let attempts = 0;

async function flakyFunction() {
  attempts += 1;
  console.log(`Attempt ${attempts}`);

  // Fail the first four attempts, then succeed on the fifth.
  if (attempts < 5) {
    throw new Error('Temporary failure');
  }

  return 'success';
}

async function main() {
  try {
    const result = await retry(flakyFunction, { retries: 5 });
    console.log('Result:', result);
  } catch (error) {
    console.error('All retry attempts failed:', error.message);
    process.exitCode = 1;
  }
}

main();

