'use strict';

// Example: retry a flaky async function with acme-retry.
//
// This workspace does not currently contain node_modules/acme-retry, so this
// example uses the most common retry-package shape: either the package itself
// is a function or it exposes a retry function.

const acmeRetry = require('acme-retry');

let calls = 0;

async function flakyFunction() {
  calls += 1;
  console.log(`Attempt ${calls}`);

  // Fail the first four calls, then succeed on the fifth.
  if (calls < 5) {
    throw new Error('Temporary failure');
  }

  return 'success';
}

async function main() {
  const retry =
    typeof acmeRetry === 'function'
      ? acmeRetry
      : acmeRetry.retry || acmeRetry.default;

  if (typeof retry !== 'function') {
    throw new TypeError(
      'acme-retry did not export a retry function. Check the package API.'
    );
  }

  const result = await retry(flakyFunction, {
    retries: 5,
    onRetry(error, attempt) {
      console.log(`Retrying after attempt ${attempt}: ${error.message}`);
    },
  });

  console.log(`Result: ${result}`);
}

main().catch((error) => {
  console.error(`Failed after retries: ${error.message}`);
  process.exitCode = 1;
});

